import numpy as np, json
from collections import Counter
def solve(I):
    I=[r[:] for r in I]; H=len(I); W=len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    O=[r[:] for r in I]
    def mark(r,c,v):
        if 0<=r<H and 0<=c<W and O[r][c]==bg: O[r][c]=v
    ones=[(r,c) for r in range(H) for c in range(W) if I[r][c]==1]
    twos=[(r,c) for r in range(H) for c in range(W) if I[r][c]==2]
    for r,c in ones:
        for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]: mark(r+dr,c+dc,7)
    for r,c in twos:
        for dr in (-1,1):
            for dc in (-1,1): mark(r+dr,c+dc,4)
    return O
